/* 📱 Telefonda «orqaga» (2026-10-19, Otabek): ochiq oyna bo'lsa — o'shani yopadi (✕/← kabi); bosh sahifada — «Saytdan chiqmoqchimisiz?» deb so'raydi */
const BK={armed:false,leaving:false};
function bkArm(){ if(IN_ARTIFACT||BK.armed||BK.leaving) return; try{ history.pushState({bk:1},"",location.href); BK.armed=true; }catch(e){} }
function bkTop(){ const L=[...document.querySelectorAll("body > [role=dialog]")].filter(e=>!e.hidden&&e.id!=="acc"&&getComputedStyle(e).display!=="none"); if(!L.length) return null;
  return L.map((e,i)=>({e,i,z:parseInt(getComputedStyle(e).zIndex)||0})).sort((a,b)=>b.z-a.z||b.i-a.i)[0].e; }
function bkCloseBtn(o){ if(o.id==="viewer") return document.getElementById("v-close"); return [...o.querySelectorAll("button")].find(b=>Object.values(b.dataset).includes("close")); }
function bkAsk(){ const ru=state.lang==="ru", d=document.createElement("div"); d.id="bk-ask"; d.className="bk-ask"; d.setAttribute("role","dialog"); d.setAttribute("aria-modal","true");
  d.innerHTML=`<div class="bk-box"><div class="bk-i">👋</div><b>${ru?"Выйти с сайта?":"Saytdan chiqmoqchimisiz?"}</b><div class="bk-b"><button type="button" class="bk-out" data-bk="out">${ru?"Выйти":"Chiqish"}</button><button type="button" class="bk-stay" data-bk="stay">${ru?"Остаться":"Qolish"}</button></div></div>`;
  document.body.appendChild(d); setTimeout(()=>{ const s=d.querySelector(".bk-stay"); if(s) s.focus(); },30);
  d.addEventListener("click",e=>{ const b=e.target.closest("[data-bk]"); if(!b&&e.target!==d) return; d.remove();
    if(b&&b.dataset.bk==="out"){ BK.leaving=true; const n=BK.armed?2:1; BK.armed=false; history.go(-n); setTimeout(()=>{ BK.leaving=false; },1500); } else bkArm(); }); }
if(!IN_ARTIFACT){
  ["pointerdown","keydown","touchstart"].forEach(t=>window.addEventListener(t,()=>{ if(!BK.armed) bkArm(); },{capture:true,passive:true}));
  window.addEventListener("popstate",()=>{ if(BK.leaving) return; BK.armed=false;
    const ask=document.getElementById("bk-ask"); if(ask){ ask.remove(); bkArm(); return; } /* savol ochiq turganda yana «orqaga» — qoladi */
    const o=bkTop(); if(o){ const b=bkCloseBtn(o); if(b) b.click(); else { o.hidden=true; document.body.style.overflow=""; } bkArm(); return; }
    bkAsk(); bkArm(); });
}
/* 🔄 Sayt yangilansa — ochiq turgan sahifada "Yangilash" tugmasi (eski versiya ishlab qolmasin, 2026-10-19, Otabek) */
(()=>{ if(IN_ARTIFACT) return; let tag=null;
  const get=()=>fetch(location.pathname,{method:"HEAD",cache:"no-store"}).then(r=>r.ok?(r.headers.get("etag")||r.headers.get("last-modified")):null).catch(()=>null);
  get().then(t=>{ tag=t; });
  const show=()=>{ if(document.getElementById("upd-t")) return; const b=document.createElement("button"); b.type="button"; b.id="upd-t"; b.className="upd-t";
    b.textContent=state.lang==="ru"?"🔄 Есть новая версия — обновить":"🔄 Yangi versiya bor — yangilash"; b.addEventListener("click",()=>location.reload()); document.body.appendChild(b); };
  const chk=()=>{ if(document.hidden||!tag) return; get().then(t=>{ if(t&&t!==tag) show(); }); };
  document.addEventListener("visibilitychange",chk); window.addEventListener("focus",chk); setInterval(chk,5*60*1000);
})();
