/* Audio: butun faylni blob qilib yuklaymiz — iOS Safari artifact serverida davomiylikni ko'rmay "Live-Übertragung" deb ko'rsatardi (2026-10-17) */
const AUD={};
function audFetch(url, onp){
  if(AUD[url]&&AUD[url].url) return Promise.resolve(AUD[url].url);
  if(AUD[url]&&AUD[url].p){ if(onp) AUD[url].cbs.push(onp); return AUD[url].p; }
  const rec=AUD[url]={cbs:onp?[onp]:[]};
  rec.p=(async()=>{
    const r=await fetch(url); if(!r.ok) throw new Error("http "+r.status);
    const total=+r.headers.get("content-length")||0; let blob;
    if(r.body&&r.body.getReader&&total){ const rd=r.body.getReader(), parts=[]; let got=0;
      for(;;){ const {done,value}=await rd.read(); if(done) break; parts.push(value); got+=value.length; rec.cbs.forEach(f=>f(Math.min(99,Math.round(got/total*100)))); }
      blob=new Blob(parts,{type:"audio/mpeg"}); }
    else blob=new Blob([await r.arrayBuffer()],{type:"audio/mpeg"});
    rec.url=URL.createObjectURL(blob); return rec.url;
  })().catch(e=>{ delete AUD[url]; throw e; });
  return rec.p;
}
function audAttach(au, url, st){
  if(st) st.textContent=t("audWait");
  audFetch(url, pc=>{ if(st && au.dataset.src===url) st.textContent=t("audWait")+" "+pc+"%"; })
    .then(b=>{ if(au.dataset.src!==url) return; au.src=b; if(st) st.textContent=""; })
    .catch(()=>{ if(au.dataset.src!==url) return; au.src=url; if(st) st.textContent=""; });
}
document.addEventListener("click",e=>{
  const b=e.target.closest(".hw-aload"); if(!b) return;
  const box=b.closest(".hw-aud"), url=box.dataset.src;
  box.innerHTML=`<span class="st">${esc(t("audWait"))}</span>`; const st=box.querySelector(".st");
  audFetch(url, pc=>{ st.textContent=t("audWait")+" "+pc+"%"; }).then(bl=>{
    box.innerHTML=`<audio controls preload="auto"></audio>`; const au=box.querySelector("audio"); au.src=bl; const pr=au.play(); if(pr&&pr.catch) pr.catch(()=>{});
  }).catch(()=>{ box.innerHTML=`<button type="button" class="ext hw-aload">🎧 ${esc(t("audErr"))}</button>`; });
});
/* ===== Wortschatz LERNEN (Quizlet uslubida) — 2026-10-17 =====
   Ma'lumot: <script id="lern-data"> — Wortschatzliste PDF'laridan olingan so'zlar.
   Lernen: avval 4 variantli test (RU → DE), keyin yozish. Ikkalasi to'g'ri bo'lsa — "o'rganildi".
   Karteikarten: kartani aylantirish, "Bilaman / Bilmayman". Natija telefonda saqlanadi (localStorage). */
function lernData(){ if(!window.__LERN){ try{ window.__LERN=JSON.parse(document.getElementById("lern-data").textContent); }catch(e){ window.__LERN={}; } try{ lrnAllBuild(window.__LERN); }catch(e){} } return window.__LERN; }
/* 🧠 Butun daraja bitta ro'yxatda: A1 = L1–24, A2 = L1–24, tilga mos (ru/uz). Progress eski ro'yxatlarda saqlanadi (2026-10-21, Otabek: «bitta tugma — A1 bo'lsa to'liq A1, A2 bo'lsa to'liq A2, tiliga mos») */
function lrnAllBuild(D){ const G={};
  Object.keys(D).forEach(id=>{ const d=D[id]; if(d.kind==="perfekt"||d.parts) return; const m=id.match(/^(A1|A2|B1)-\w+-([ru])-/); if(!m) return; (G[m[1]+"-"+m[2]]=G[m[1]+"-"+m[2]]||[]).push(id); });
  Object.keys(G).forEach(k=>{ const ids=G[k].sort((a,b)=>Math.min(...Object.keys(D[a].les).map(Number))-Math.min(...Object.keys(D[b].les).map(Number))); if(ids.length<2) return;
    const [lv,ln]=k.split("-"), o={les:{},sec:[],it:[],mt:{},fns:[],fn:{},mtu:{},parts:[],all:lv,lang:ln,title:"Wortschatz "+lv+" · "+(ln==="r"?"Deutsch–Russisch":"Deutsch–O‘zbekcha")};
    ids.forEach(id=>{ const d=D[id], off=o.it.length, so=o.sec.length, fo=o.fns.length; Object.assign(o.les,d.les); (d.sec||[]).forEach(x=>o.sec.push(x)); (d.fns||[]).forEach(x=>o.fns.push(x));
      d.it.forEach(r=>{ const c=r.slice(); c[1]=r[1]+so; o.it.push(c); });
      ["mt","mtu"].forEach(f=>{ if(d[f]) for(const i in d[f]) o[f][+i+off]=d[f][i]; }); if(d.fn) for(const i in d.fn) o.fn[+i+off]=d.fn[i]+fo;
      o.parts.push({id,off,n:d.it.length}); });
    D[lv+"-all-"+ln+"-Wortschatz-"+lv]=o; }); }
/* Perfekt / Reflexiv ro'yxatlari — sayt tiliga mos (uz → -u-, ru → -r-), bo'lmasa ruscha (2026-10-22) */
function lrnPerfLink(lvl){ const D=lernData(), want=state.lang==="ru"?"r":"u", pick=re=>{ const ks=Object.keys(D).filter(k=>k.startsWith(lvl+"-")&&D[k].kind==="perfekt"&&re.test(k)); return ks.find(k=>k.split("-")[2]===want)||ks.find(k=>k.split("-")[2]==="r")||ks[0]; };
  const p=pick(/Perfekt/), r=pick(/Reflexive/); return (p?`<button type="button" class="vo-btn" data-lern="${p}">📗 Verben mit Perfekt →</button>`:"")+(r?`<button type="button" class="vo-btn" data-lern="${r}">🔁 Reflexive Verben →</button>`:""); }
function lrnAllId(lvl,lang){ const D=lernData(), want=lang==="ru"?"r":"u", a=lvl+"-all-"+want+"-Wortschatz-"+lvl, b=lvl+"-all-r-Wortschatz-"+lvl; return D[a]?a:(D[b]?b:null); }
