function spMode(it){ const h=String(it.h||""); if(/sprechen Sie (die Sätze )?nach/.test(h)) return "n"; if(/^Reagieren Sie mit|^Antworten Sie mit \*(ja|nein|Nein, danke|Doch|auf jeden)/.test(h)) return "k"; if(SP_GRAM.test(h)) return "g"; if(SP_KOMM.test(h)) return "k"; return "i"; }
const SP_STOP=new Set("der die das den dem des ein eine einen einem einer eines und oder aber ich du er sie es wir ihr mir dir mich dich uns euch ihm ihn ihnen mit zu zum zur in im am an auf aus bei von vom für ist sind bin bist seid hat habe hast haben sehr so noch auch".split(" "));
function spFold(w){ return String(w).replace(/ä/g,"a").replace(/ö/g,"o").replace(/ü/g,"u").replace(/ß/g,"ss").replace(/-/g,""); }
/* sonlar: «zehn» = «10», «fünfundzwanzig» = «25», «dreizehnte» = «13» — Azure ko'pincha raqam yozadi (2026-10-22) */
const SP_N1={null:0,ein:1,eins:1,eine:1,zwei:2,drei:3,vier:4,funf:5,sechs:6,sieben:7,acht:8,neun:9,zehn:10,elf:11,zwolf:12,dreizehn:13,vierzehn:14,funfzehn:15,sechzehn:16,siebzehn:17,achtzehn:18,neunzehn:19,erst:1,dritt:3,siebt:7};
