  if(mode==="n"){ /* takrorlash: matnsiz so'rov ham — nima eshitilganini bilish uchun (2026-10-22) */ const ref=String(it.a).replace(/\s*\([^)]*\)\s*/g," ").trim(); const [u,r]=await Promise.all([spAzOnce(SDK,T,wav,"",false).catch(()=>null),spAzOnce(SDK,T,wav,ref,true)]); if(!r&&!u) return null; const R=r||u;
    const sc=R.pron||(R.acc?Math.round(R.acc*.5+R.flu*.25+R.com*.25):null); return {mode,conf:u?u.conf:R.conf,sc:R.acc||R.pron?sc:null,acc:R.acc,com:R.com,flu:R.flu,W:R.W,txt:(u&&u.txt)||R.txt}; }
  let r=await spAzOnce(SDK,T,wav,"",false); if(!r) return null; const txt=r.txt, conf=r.conf;
