  const A1=String(LR.id).startsWith("A1"); /* A1 — osonroq: Verbinden (kitobdagi "Wer sagt was? Verbinden Sie"), chat, so'z banki (2026-10-19, Otabek) */
  const fresh=lrnShuffle(pool.filter(x=>!st[x.i])), old=lrnShuffle(pool.filter(x=>st[x.i])); const lim=A1?6:8, take=(fresh.length>lim&&fresh.length-lim<=2)?fresh.length:lim; /* 1–2 ta ibora keyingi mashg‘ulotga qolib ketmasin */ const items=[...fresh,...old].slice(0,take);
