const at=k=>ACCT[state.lang][k];
function accUsers(){ try{ return JSON.parse(localStorage.getItem("acc:users")||"{}")||{}; }catch(e){ return {}; } }
function accKeyOf(name){ return name.toLowerCase().normalize("NFC").replace(/[’‘`´']/g,"").replace(/\s+/g,"_"); }
async function accHash(s){
  try{ const b=await crypto.subtle.digest("SHA-256",new TextEncoder().encode(s)); return [...new Uint8Array(b)].map(x=>x.toString(16).padStart(2,"0")).join(""); }
  catch(e){ let h1=0x811c9dc5,h2=0; for(const ch of s){ const c=ch.codePointAt(0); h1=Math.imul(h1^c,16777619)>>>0; h2=(Math.imul(h2,31)+c)>>>0; } return "f"+h1.toString(16)+h2.toString(16); }
}
function accEl(){ return document.getElementById("acc"); }
function accLangRow(){ return `<div class="acc-lang">${["uz","ru"].map(l=>`<button type="button" data-acclang="${l}" aria-pressed="${state.lang===l}">${l.toUpperCase()}</button>`).join("")}</div>`; }
let ACC_MODE="reg";
