const DUT={uz:{t:"⚔️ Duel", mode:"⚔️ Duel", modeD:"Do‘stingiz bilan 1 ga 1: bir xil savollar, 1 daqiqa, kim ko‘p topadi?",
    made:"Duel xonasi tayyor!", share:"Havolani raqibingizga yuboring. U kirishi bilan duel boshlanadi.", wait:"⏳ Raqib kutilmoqda…", joined:n=>`⚔️ ${n} qo‘shildi!`,
    ready:"✋ Tayyorman", waitR:"Raqib tayyorlanmoqda…", name:"Ismingiz", namePh:"Ism va familiya", join:"Duelga kirish", errName:"Ismingizni yozing",
    win:n=>`🏆 ${n} yutdi!`, youWin:"🏆 Siz yutdingiz!", youLose:"Bu safar raqib yutdi 💪", draw:"🤝 Durang!", rev:"🔁 Revansh", revWait:"Raqib revanshga rozi bo‘lishini kuting…", revAsk:n=>`${n} revansh so‘rayapti!`,
    close:"Yopish", spect:"👀 Siz tomoshabinsiz", full:"Bu duelda allaqachon ikki kishi o‘ynayapti — siz tomosha qilasiz.", tg:"📤 Telegram", copy:"📋 Nusxalash", copied:"✓ Nusxalandi",
    vs:"vs", round:n=>`${n}-raund`, choose:"To‘g‘ri tarjimani tanlang", bad:"Havola noto‘g‘ri yoki eskirgan.", tgText:(n,t)=>`⚔️ ${n} sizni duelga chaqiryapti: ${t}. 1 daqiqa, bir xil savollar — kim yutadi?`, left:"Raqib chiqib ketdi"},
  ru:{t:"⚔️ Дуэль", mode:"⚔️ Дуэль", modeD:"Один на один с другом: одинаковые вопросы, 1 минута — кто больше?",
    made:"Комната дуэли готова!", share:"Отправьте ссылку сопернику. Как только он войдёт — начнём.", wait:"⏳ Ждём соперника…", joined:n=>`⚔️ ${n} присоединился!`,
    ready:"✋ Я готов(а)", waitR:"Соперник готовится…", name:"Ваше имя", namePh:"Имя и фамилия", join:"Войти в дуэль", errName:"Напишите имя",
    win:n=>`🏆 Победил(а) ${n}!`, youWin:"🏆 Вы победили!", youLose:"В этот раз победил соперник 💪", draw:"🤝 Ничья!", rev:"🔁 Реванш", revWait:"Ждём, когда соперник согласится…", revAsk:n=>`${n} просит реванш!`,
    close:"Закрыть", spect:"👀 Вы зритель", full:"В этой дуэли уже играют двое — вы смотрите.", tg:"📤 Telegram", copy:"📋 Копировать", copied:"✓ Скопировано",
    vs:"vs", round:n=>`Раунд ${n}`, choose:"Выберите правильный перевод", bad:"Ссылка неверная или устарела.", tgText:(n,t)=>`⚔️ ${n} вызывает вас на дуэль: ${t}. 1 минута, одинаковые вопросы — кто победит?`, left:"Соперник вышел"}};
const dt=k=>DUT[state.lang==="ru"?"ru":"uz"][k];
const DU={};
function duEl(){ let e=document.getElementById("duel"); if(!e){ e=document.createElement("div"); e.id="duel"; e.className="lrn"; e.setAttribute("role","dialog"); e.setAttribute("aria-modal","true"); e.hidden=true; document.body.appendChild(e); } return e; }
function duLink(code){ return (/github\.io$/.test(location.hostname)||!/claude/.test(location.hostname)&&location.protocol!=="file:" ? location.origin+location.pathname : CH_SITE)+"?du="+code; }
function duHead(sub){ return `<div class="lrn-bar"><button class="btn" data-du="close" aria-label="✕">✕</button><div class="lrn-tt"><b>${esc(dt("t"))}</b><small>${esc(chTitle(DU.c))}</small></div>${sub||""}</div>`; }
function duCreate(){ if(!LR.id||!LR.sel.size) return;
  const c={v:1,l:LR.id,s:[...LR.sel].sort((a,b)=>a-b),r:Math.floor(Math.random()*2147483647),c:(ACC.name||"").split(" ")[0]||"",t:Date.now()};
  const code=chB64e(JSON.stringify(c)); lrnClose(); history.replaceState(null,"","?du="+code); duOpen(code,true); }
/* o'yinchilar: birinchi kirgan ikkitasi */
function duPlayers(){ const P=Object.entries(DU.P).filter(([id,p])=>p&&p.j).sort((a,b)=>a[1].j-b[1].j||(a[0]<b[0]?-1:1)); return P.slice(0,2).map(([id,p])=>({id,...p})); }
function duRole(){ const L=duPlayers(); return L.some(p=>p.id===DU.me)? "player" : (DU.joined? (L.length<2?"player":"spect") : "none"); }
function duOpp(){ return duPlayers().find(p=>p.id!==DU.me)||null; }
function duPub(){ if(!DU.mq||!DU.joined) return; DU.mq.pub(DU_NS+DU.id+"/p/"+DU.me, JSON.stringify({n:DU.name,hl:hpMyLv(),j:DU.j,r:DU.r,rd:DU.rd,s:DU.s,lt:DU.lt,st:DU.st,h:DU.h,hp:DU.hp,cb:DU.cb,cx:DU.cx|0,t:Date.now()}), true); }
function duOpen(code,creator){
  let c=null; try{ c=JSON.parse(chB64d(code)); }catch(e){}
  const el=duEl(); el.hidden=false; document.body.style.overflow="hidden";
  if(!c||!(c.xs?c.xs.length:c.x?exData()[c.x]:lernData()[c.l])||chQuestions(c).length===0){ el.innerHTML=`<div class="lrn-bar"><button class="btn" data-du="close">✕</button><div class="lrn-tt"><b>${esc(dt("t"))}</b></div></div><div class="lrn-body"><div class="lrn-card"><p>${esc(dt("bad"))}</p></div></div>`; return; }
  let me=store.get("chme"); if(!me){ me=Math.random().toString(36).slice(2,10); store.set("chme",me); }
  Object.assign(DU,{cx:0,c,code,id:chHash("du:"+code),me,P:{},ctl:{},joined:false,name:ACC.name||store.get("chname")||"",j:0,r:1,rd:false,s:0,lt:0,st:"lobby",phase:"lobby",h:{},creator:!!creator});
  if(DU.mq) DU.mq.end();
  DU.mq=mqMulti(cl=>{ cl.subscribe(DU_NS+DU.id+"/#",{qos:1}); duPub(); duNet(); },(t,m)=>duMsg(t,m));
  if(creator||DU.name){ if(DU.name){ DU.joined=true; DU.j=Date.now(); } }
  clearInterval(DU.tk); DU.tk=setInterval(duTick,250); DU.openT=Date.now();
  duRender();
}
function duNet(){ const e=document.getElementById("du-net"); if(e) e.textContent= DU.mq&&DU.mq.ok()? "🟢" : (Date.now()-DU.openT>10000? "🔴 "+ct("netBad") : "⏳"); }
function duMsg(t,m){
  const parts=t.split("/"), kind=parts[parts.length-2], last=parts[parts.length-1];
  if(last==="go"){ try{ const d=JSON.parse(m); if(d&&d.r) DU.ctl[d.r]=d; }catch(e){} duCheckGo(); return; }
  if(kind==="p"){ if(last===DU.me) return; if(!m){ delete DU.P[last]; } else { try{ const d=JSON.parse(m); if(d&&d.j){ { const was=(DU.P[last]||{}).cx|0; if((d.cx|0)>was&&DU.phase==="play") setTimeout(()=>{ try{ const ru=state.lang==="ru"; let w=document.getElementById("gcx-w"); if(!w){ w=document.createElement("div"); w.id="gcx-w"; w.className="kgp-cxw"; document.body.appendChild(w); } w.textContent=`👀 ${ru?"Соперник вышел из игры!":"Raqibingiz o‘yindan chiqib ketdi!"} (${d.cx|0})`; w.classList.remove("show"); void w.offsetWidth; w.classList.add("show"); setTimeout(()=>w.classList.remove("show"),3000); }catch(e){} },0); } DU.P[last]={cx:Math.min(99,d.cx|0),hl:Math.min(4,d.hl|0),n:String(d.n||"?").slice(0,30),j:+d.j,r:d.r|0,rd:!!d.rd,s:d.s|0,lt:+d.lt||0,st:d.st,h:(d.h&&typeof d.h==="object")?d.h:{},hp:d.hp==null?3:d.hp|0,cb:d.cb|0,t:d.t||0};
          if(DU.phase==="play"&&d.st==="play"&&(d.cb|0)>=3&&(d.cb|0)>(DU.oCb||0)&&((d.cb|0)===3||(d.cb|0)===5)) duToast(`${String(d.n||"").split(" ")[0]} 🔥×${(d.cb|0)>=5?3:2}!`); if(d.st==="play") DU.oCb=d.cb|0; } }catch(e){} } }
  duSync();
}
/* o'z yozuvimizni ham P ga qo'shamiz (hisob-kitob uchun) */
function duSelf(){ if(DU.joined) DU.P[DU.me]={n:DU.name,j:DU.j,r:DU.r,rd:DU.rd,s:DU.s,lt:DU.lt,st:DU.st,h:DU.h,hp:DU.hp,cb:DU.cb}; else delete DU.P[DU.me]; }
function duToast(t){ const e=document.getElementById("du-toast"); if(!e) return; e.textContent=t; e.hidden=false; e.classList.remove("show"); void e.offsetWidth; e.classList.add("show"); clearTimeout(DU.toT); DU.toT=setTimeout(()=>{ e.hidden=true; },1300); }
function duSync(){ duSelf(); if(!DU.joined){ const L=duPlayers(); if(L.length>=2&&!document.querySelector("#duel [data-du=watch]")) duRender(); return; }
  const o=duOpp(), role=duRole();
  /* revansh: raqib yangi raundga o'tgan bo'lsa */
  if(role==="player"&&o&&o.r>DU.r&&DU.phase==="end"){ DU.revAsk=true; }
  duCheckGo();
  if(DU.phase==="lobby"||DU.phase==="end"||DU.phase==="spect") duRender(); else duScore();
}
function duCheckGo(){ duSelf(); const L=duPlayers(); if(L.length<2) return;
  const role=duRole(); const [a,b]=L;
  if(role==="player"){
    if(DU.phase!=="lobby"&&DU.phase!=="end") return;
    if(a.rd&&b.rd&&a.r===b.r&&a.r===DU.r){ if(!DU.ctl[DU.r]&&L[0].id===DU.me){ DU.ctl[DU.r]={r:DU.r,go:Date.now()}; DU.mq.pub(DU_NS+DU.id+"/go",JSON.stringify(DU.ctl[DU.r]),true); }
      if(DU.ctl[DU.r]&&DU.phase!=="count") duCount(); }
  }
}
function duCount(){ if(DU.phase==="count"||DU.phase==="play") return; DU.phase="count"; let k=3;
  const tick=()=>{ if(DU.phase!=="count") return; if(k===0){ duPlay(); return; } const o=duOpp();
    duEl().innerHTML=duHead()+`<div class="lrn-body"><div class="du-vsbig"><b>${esc(DU.name)}</b><span>${esc(dt("vs"))}</span><b>${esc(o?o.n:"?")}</b></div><div class="ch-cd">${k}</div></div>`; k--; setTimeout(tick,800); };
  tick(); }
function duPlay(){
  const c=Object.assign({},DU.c,{r:(DU.c.r+DU.r*7919)>>>0}); DU.qs=chQuestions(c);
  Object.assign(DU,{phase:"play",st:"play",s:0,okN:0,lt:0,qi:0,t0:performance.now(),hp:3,cb:0,oCb:0}); duPub();
  duEl().innerHTML=duHead(`<span class="ch-time" id="du-time">${duLim()}</span>`)+`<div class="lrn-body">
    <div class="ch-bar"><i id="du-tb" style="width:100%"></i></div>
    <div id="du-score"></div>
    <div class="lrn-card" id="du-card"></div><div class="du-toast" id="du-toast" hidden></div></div>`;
  duScore(); duQ();
}
function duTick(){ duNet();
  if(DU.phase==="play"){ const lim=duLim(), left=Math.max(0,lim-(performance.now()-(DU.qT||DU.t0))/1000), t=document.getElementById("du-time"), b=document.getElementById("du-tb");
    if(t){ t.textContent=Math.ceil(left); t.classList.toggle("hurry",left<=3); } if(b){ b.style.width=(left/lim*100)+"%"; b.classList.toggle("hurry",left<=3); }
    if(left<=0&&!DU.lock) duAnswer(-1); if((performance.now()-DU.t0)/1000>120) duEnd(); }
}
function duScoreHTML(){ const L=duPlayers(); const me=L.find(p=>p.id===DU.me)||L[0], o=L.find(p=>p!==me);
  if(!me) return ""; const s1=me.s||0, s2=o?(o.s||0):0, tot=Math.max(4,s1+s2), pos=50+((s1-s2)/tot)*50;
  const live=DU.phase==="play"||DU.phase==="end", hp=p=>live?`<i class="du-hp">${duHearts(p.hp==null?3:p.hp)}</i>`:"", cb=p=>live&&p.st==="play"&&(p.cb|0)>=3?`<i class="du-cb">🔥×${(p.cb|0)>=5?3:2}</i>`:"";
  return `<div class="du-sc"><div class="du-p du-a"><b>${esc(me.n.split(" ")[0])}${me.id===DU.me?` <small>(${esc(ct("you"))})</small>`:""}</b>${hp(me)}${cb(me)}<span>${s1}</span></div>
    <div class="du-tug"><i class="du-l" style="width:${Math.max(4,Math.min(96,pos))}%"></i><em style="left:${Math.max(4,Math.min(96,pos))}%">⚔️</em></div>
    <div class="du-p du-b"><b>${esc(o?o.n.split(" ")[0]:"…")}</b>${o?hp(o):""}${o?cb(o):""}<span>${s2}</span></div></div>`; }
function duScore(){ const e=document.getElementById("du-score"); if(e) e.innerHTML=duScoreHTML(); }
function duQ(){ const q=DU.qs[DU.qi%DU.qs.length]; DU.cur=q; DU.lock=false; DU.qT=performance.now(); const card=document.getElementById("du-card"); if(!card) return; const t=document.getElementById("du-time"); if(t) t.textContent=duLim();
  card.innerHTML=`<div class="du-lim">${DU.qi+1} / 15 · ⏱ ${duLim()} s${duMult()>1?` · <b class="du-cbp">🔥×${duMult()}</b>`:""}</div><div class="ch-q">${esc(q.q)}</div><div class="lrn-ask">${esc(DU.c.x?(state.lang==="ru"?"Выберите правильный ответ":"To‘g‘ri javobni tanlang"):dt("choose"))}</div><div class="lrn-opts">${q.o.map((o,k)=>`<button type="button" class="lrn-opt" data-duo="${k}"><span class="k">${k+1}</span>${esc(o)}</button>`).join("")}</div>`; }
function duAnswer(k){ if(DU.phase!=="play"||DU.lock) return; DU.lock=true; const q=DU.cur, ok=k>=0&&q.o[k]===q.a, card=document.getElementById("du-card");
  if(ok){ const left=Math.max(0,duLim()-(performance.now()-DU.qT)/1000), was=duMult(); DU.cb=(DU.cb||0)+1; DU.okN=(DU.okN||0)+1; const pts=Math.round((100+left*20)*was); DU.s+=pts; DU.lt=Math.round(performance.now()-DU.t0); const pp=document.createElement("div"); pp.className="ch-pts"; pp.textContent="+"+pts+(was>1?" 🔥":""); card.appendChild(pp); }
  else { DU.cb=0; DU.hp=Math.max(0,(DU.hp==null?3:DU.hp)-1); if(navigator.vibrate) try{ navigator.vibrate(60); }catch(e){} }
  card.querySelectorAll(".lrn-opt").forEach((b,j)=>{ b.disabled=true; if(q.o[j]===q.a) b.classList.add("ok"); else if(j===k) b.classList.add("bad"); });
  card.classList.remove("ch-flash-ok","ch-flash-bad"); void card.offsetWidth; card.classList.add(ok?"ch-flash-ok":"ch-flash-bad");
  duPub(); duSelf(); duScore();
  if(DU.hp<=0||DU.qi+1>=15){ setTimeout(()=>{ if(DU.phase==="play") duEnd(); },700); return; } /* 15 savol (2026-10-22, Otabek) */
  setTimeout(()=>{ if(DU.phase!=="play") return; DU.qi++; duQ(); }, ok?250:750); }
function duEnd(){ if(DU.phase!=="play") return; try{ actEv("game","du"); }catch(e){} try{ gpAdd("du",(DU.id||"")+":"+DU.r,Math.round((DU.s|0)/20)); }catch(e){} DU.phase="end"; DU.st="done"; DU.rd=false; DU.h[DU.r]=[DU.s,DU.lt]; try{ actLog("du","du","⚔️ Duel · "+(DU.s|0)+" ball",DU.okN|0,DU.qi|0); /* avval ball «so'z» deb yozilardi (2026-10-23) */ }catch(e){} const ks=Object.keys(DU.h).map(Number).sort((a,b)=>b-a); ks.slice(3).forEach(k=>delete DU.h[k]); duPub(); duRender(); }
function duRes(p,R){ const x=p.h&&p.h[R]; if(x) return {s:x[0]|0,lt:+x[1]||0}; if(p.r===R&&p.st==="done") return {s:p.s,lt:p.lt}; return null; }
function duResult(R){ const L=duPlayers(); if(L.length<2) return null; R=R||DU.r; const ra=duRes(L[0],R), rb=duRes(L[1],R);
  if(!ra||!rb) return {wait:true}; const a={...L[0],...ra}, b={...L[1],...rb};
  if(a.s===b.s&&a.lt===b.lt) return {draw:true,a,b}; const w=(a.s>b.s||(a.s===b.s&&a.lt<b.lt))?a:b; return {w,a,b}; }
function duRender(){
  const el=duEl(); duSelf(); const role=duRole(), L=duPlayers(), o=duOpp(), url=duLink(DU.code);
  if(!DU.joined){ /* kirish: ism */
    const full=L.length>=2;
    el.innerHTML=duHead()+`<div class="lrn-body"><div class="lrn-card">${DU.c.c?`<h3>${esc(ct("from")(DU.c.c))}</h3>`:""}<p class="ch-big"><b>${esc(chTitle(DU.c))}</b></p>
      ${full?`<p class="ch-big">${esc(dt("full"))}</p><button type="button" class="btn primary" data-du="watch">👀 OK</button>`:`<label class="acc-lb">${esc(dt("name"))}<input class="ch-in" id="du-name" maxlength="30" placeholder="${esc(dt("namePh"))}" value="${esc(DU.name)}"></label><div class="acc-st err" id="du-err"></div>
      <button type="button" class="btn primary" data-du="join">${esc(dt("join"))} →</button>`}<p class="ch-net" id="du-net"></p></div>${L.length?`<div class="lrn-card">${duScoreHTML()}</div>`:""}</div>`;
    duNet(); return; }
  if(role==="spect"||DU.phase==="spect"){ DU.phase="spect"; const L2=duPlayers(), R2=L2.length===2?Math.min(L2[0].r,L2[1].r):1; const r=duResult(R2);
    el.innerHTML=duHead()+`<div class="lrn-body"><p class="ch-big">${esc(dt("spect"))}</p><div class="lrn-card du-big">${duScoreHTML()}${r&&r.w?`<h3 class="du-win">${esc(dt("win")(r.w.n))}</h3>`:r&&r.draw?`<h3 class="du-win">${esc(dt("draw"))}</h3>`:""}</div></div>`; return; }
  if(DU.phase==="lobby"){
    const me=L.find(p=>p.id===DU.me);
    el.innerHTML=duHead()+`<div class="lrn-body"><div class="lrn-card">
      ${!o?`<h3>${esc(DU.creator?dt("made"):dt("wait"))}</h3><p class="ch-big">${esc(dt("share"))}</p><div class="ch-link">${esc(url)}</div>
        <div class="ch-btns"><a class="btn primary" target="_blank" rel="noopener" href="https://t.me/share/url?url=${encodeURIComponent(url)}&text=${encodeURIComponent(dt("tgText")(DU.name.split(" ")[0]||"⚔️",chTitle(DU.c)))}">${esc(dt("tg"))}</a><button type="button" class="btn" data-du="copy">${esc(dt("copy"))}</button></div>
        <div class="lt-wait"><div class="lt-dots"><i></i><i></i><i></i></div><b>${esc(dt("wait"))}</b></div>`
      :`<div class="du-vsbig"><b>${esc(DU.name)}${hpBadgeLv(hpMyLv(),true)}</b><span>${esc(dt("vs"))}</span><b>${esc(o.n)}${hpBadgeLv(o.hl,true)}</b></div><p class="ch-big du-c">⏱ 10→4 s · ❤️❤️❤️ · 🔥 ${esc(dt("round")(DU.r))}</p>
        ${DU.rd?`<div class="lt-wait"><div class="lt-dots"><i></i><i></i><i></i></div><b>${esc(o.rd?"…":dt("waitR"))}</b></div>`:`<button type="button" class="btn primary tp-big" data-du="ready">${esc(dt("ready"))}</button>`}
        <p class="ch-net du-c">${o.rd?"✅ "+esc(o.n)+" ✋":"⏳ "+esc(o.n)}</p>`}
      <p class="ch-net" id="du-net"></p></div></div>`;
    duNet(); return; }
  if(DU.phase==="end"){ const r=duResult();
    const head= !r||r.wait? `<div class="lt-wait"><div class="lt-dots"><i></i><i></i><i></i></div><b>${esc(o?o.n:"")}…</b></div>`
      : r.draw? `<div class="big">🤝</div><h3 class="du-win">${esc(dt("draw"))}</h3>` : r.w.id===DU.me? `<div class="big">🏆</div><h3 class="du-win">${esc(dt("youWin"))}</h3>` : `<div class="big">💪</div><h3 class="du-win">${esc(dt("youLose"))}</h3>`;
    const T=duTally(), uz=state.lang!=="ru", won=r&&r.w&&r.w.id===DU.me, fin=T.me>=2||T.opp>=2, shareT=won&&o?`🏆 ${DU.name.split(" ")[0]} ${o.n.split(" ")[0]}${uz?"ni duelda yengdi":" победил(а) в дуэли"} · ${chTitle(DU.c)} · ${DU.s}:${o.s||0}`:"";
    el.innerHTML=duHead()+`<div class="lrn-body"><div class="lrn-card lrn-end">${head}${duScoreHTML()}
      ${L.length>=2?`<div class="du-tally"><span>${uz?"Raundlar":"Раунды"}: </span><b class="${T.me>T.opp?"w":T.me<T.opp?"l":""}">${T.me} : ${T.opp}</b><small> · ${uz?"3 raunddan 2 tasini yutgan — g‘olib":"победитель — 2 раунда из 3"}</small></div>`:""}
      ${fin?`<h3 class="du-win">${T.me>T.opp?"👑 "+(uz?"Siz duelni yutdingiz!":"Вы выиграли дуэль!"):"💪 "+(uz?"Duel raqibniki":"Дуэль за соперником")}</h3>`:""}
      ${shareT?`<a class="btn" target="_blank" rel="noopener" href="https://t.me/share/url?url=${encodeURIComponent(CH_SITE)}&text=${encodeURIComponent(shareT)}">✈️ ${uz?"Ulashish":"Поделиться"}</a>`:""}
      ${DU.revAsk&&o&&o.r>DU.r?`<p class="ch-big du-ask">${esc(dt("revAsk")(o.n))}</p>`:""}
      <div class="ch-btns" style="justify-content:center">${r&&!r.wait?`<button type="button" class="btn primary" data-du="rev">${esc(dt("rev"))}</button>`:""}<button type="button" class="btn" data-du="close">${esc(dt("close"))}</button></div></div></div>`;
    if(r&&!r.wait&&!DU.fx){ DU.fx=DU.r; if(r.w&&r.w.id===DU.me) ltConfetti(); }
    return; }
}
function duJoin(){ const i=document.getElementById("du-name"), nm=(i.value||"").replace(/\s+/g," ").trim();
  if(nm.length<2){ document.getElementById("du-err").textContent=dt("errName"); i.focus(); return; }
  DU.name=nm; store.set("chname",nm); DU.joined=true; DU.j=Date.now(); duPub(); duSync(); duRender(); }
function duReady(){ DU.rd=true; duPub(); duSync(); duRender(); }
