function dcDay(){ const d=new Date(Date.now()+5*3600e3); return d.toISOString().slice(0,10); } /* Toshkent sanasi */
function dcNo(day){ const d=day||dcDay(); return Math.floor((Date.UTC(+d.slice(0,4),+d.slice(5,7)-1,+d.slice(8,10))-dcEpoch())/86400e3)+1; }
