function rankSync(force){
  if(!ACC.cur||IN_ARTIFACT||tchOk()) return; /* ustoz qurilmasidan reytingga yozilmaydi */
  let c; try{ c=progCount(); }catch(e){ return; }
  const msg={nm:rkName(), n:c.n, lv:progLv(c.n), t:Date.now()};
  let last={}; try{ last=JSON.parse(store.get("rank:pub")||"{}")||{}; }catch(e){}
  if(!force && last.n===msg.n && last.nm===msg.nm && Date.now()-(last.t||0)<864e5) return;
  chLib(()=>{ if(!window.mqtt) return;
    CH_BROKERS.forEach(u=>{ try{ const cli=window.mqtt.connect(u,{clientId:"rk_"+Math.random().toString(36).slice(2,9),clean:true,connectTimeout:8000,reconnectPeriod:0});
      cli.on("connect",()=>{ cli.publish(RK_NS+rkId(), JSON.stringify(msg), {qos:1,retain:true}, ()=>{ store.set("rank:pub",JSON.stringify(msg)); setTimeout(()=>{ try{ cli.end(); }catch(e){} },500); }); });
      cli.on("error",()=>{}); setTimeout(()=>{ try{ cli.end(true); }catch(e){} },15000);
    }catch(e){} }); });
}
