function tourLinkT(){ const b=document.getElementById("tour-link"); if(!b) return; let d=false; try{ d=localStorage.getItem("tour")==="1"; }catch(e){} b.hidden=d; const ru=state.lang==="ru"; b.innerHTML=`${ru?"🧭 Экскурсия по сайту":"🧭 Sayt bo‘ylab sayohat"}<span class="tour-lx" data-tourx role="button" aria-label="${ru?"Скрыть":"Yashirish"}" title="${ru?"Скрыть":"Yashirish"}">✕</span>`; } /* ✕ — sayohat tugmasini yashirish (2026-10-23, Otabek) */ /* bir marta o‘tilgandan keyin tugma yashiriladi (2026-10-21, Otabek) */
document.addEventListener("click",e=>{ if(e.target.closest("[data-lang]")) setTimeout(tourLinkT,0); }); setTimeout(tourLinkT,0);
function tourBox(){ let b=document.getElementById("tour"); if(!b){ b=document.createElement("div"); b.id="tour"; b.innerHTML=`<div class="tour-spot" id="tour-spot"></div><div class="tour-bub" id="tour-bub" role="dialog" aria-live="polite"></div>`; document.body.appendChild(b); } return b; }
function tourFind(s){ try{ const e=typeof s==="function"?s():document.querySelector(s); return e&&e.getClientRects().length?e:null; }catch(e){ return null; } }
function tourStart(){ TOUR.on=true; TOUR.i=0; TOUR.lek=null; TOUR.prev=null; document.documentElement.classList.add("touring"); tourBox().hidden=false; try{ actEv("tour","start"); }catch(e){} tourShow(); }
function tourEnd(done){ try{ if(TOUR.prev){ const p=TOUR.prev; TOUR.prev=null; if(p.tab!==state.tab||p.type!==state.type){ state.tab=p.tab; state.type=p.type; render(); } } }catch(e){} setTimeout(()=>{ try{ if(ACC.cur&&!tchOk()&&!store.get("lvl")&&accEl().hidden) lvlAsk(); }catch(e){} },400); TOUR.on=false; cancelAnimationFrame(TOUR.raf); clearInterval(TOUR.poll); const b=document.getElementById("tour"); if(b) b.hidden=true; document.documentElement.classList.remove("touring"); try{ localStorage.setItem("tour","1"); actEv("tour",done?"done":"skip"); }catch(e){} tourLinkT(); }
function tourNext(){ TOUR.i++; tourShow(); }
/* «Bosing» yoki pufakchani bosish = yoritilgan tugmani bosish (2026-10-21, Otabek: «нажмите deganda qo‘li bilan ko‘rsatib turgan narsa bosilsin») */
function tourTap(){ const s=TOUR.cur; if(!s||!s.tap) return; const el=tourFind(s.sel); if(!el) return; const t=el.matches("button,a,input,[data-open],[data-l],[role=button]")?el:(el.querySelector("button,a,[data-open],[role=button]")||el); t.click(); }
function tourStep(){ const s=TOUR_S[TOUR.i]; if(!s) return null; if(s.dyn){ const d=s.dyn(); if(d==="done") return "done"; if(!d) return null; return Object.assign({t:{uz:d.t,ru:d.t}},d,{t:{uz:d.t,ru:d.t},_dyn:1}); } return s; }
function tourShow(){ if(!document.querySelector(".lrn:not([hidden]),.viewer:not([hidden]),.snd:not([hidden])")) document.body.style.overflow=""; clearInterval(TOUR.poll); cancelAnimationFrame(TOUR.raf); TOUR.adv=false;
  if(TOUR.i>=TOUR_S.length){ tourEnd(true); return; }
  const s0=TOUR_S[TOUR.i]; if(s0.enter) try{ s0.enter(); }catch(e){}
  let tries=0; const spot=document.getElementById("tour-spot"), bub=document.getElementById("tour-bub");
  spot.style.opacity="0"; bub.style.opacity="0";
  TOUR.poll=setInterval(()=>{ let s=tourStep(); if(s==="done"){ tourNext(); return; }
    const el=s&&!s.center?tourFind(s.sel):null;
    if(s&&(s.center||el)){ clearInterval(TOUR.poll); TOUR.cur=s; if(s.coach) try{ localStorage.setItem("coach:"+s.coach,"1"); document.querySelectorAll(".coach").forEach(c=>c.remove()); }catch(e){}
      if(el){ const r=el.getBoundingClientRect(); if(r.top<70||r.bottom>innerHeight-40) el.scrollIntoView({block:r.height>innerHeight*0.6?"start":"center",behavior:"smooth"}); }
      tourDraw(s,el); if(s.until) TOUR.poll=setInterval(()=>{ if(s.until()){ clearInterval(TOUR.poll); setTimeout(tourNext,500); } },300);
      if(s._dyn) TOUR.poll=setInterval(()=>{ const d=tourStep(); if(!d||d==="done"||d.sel!==s.sel||d.t.uz!==s.t.uz){ clearInterval(TOUR.poll); tourShow(); } },400);
      return; }
    if(++tries>(s0.dyn?40:14)){ clearInterval(TOUR.poll); tourNext(); } },250); }
function tourDraw(s,el){ const spot=document.getElementById("tour-spot"), bub=document.getElementById("tour-bub"), ru=state.lang==="ru";
  const nx=s.next?`<button type="button" class="tour-nx" data-tour="next">${tourTx(s.btn||{uz:"Keyingi →",ru:"Далее →"})}</button>`:(s.tap?`<button type="button" class="tour-tap" data-tour="tap">👆 ${ru?"Нажмите":"Bosing"}</button>`:"");
  const sol=s.until?`<button type="button" class="tour-sol" data-tour="sol">💡 ${ru?"Показать ответ":"Javobni ko‘rsat"}</button>`:"";
  bub.innerHTML=`<button type="button" class="tour-x" data-tour="skip" aria-label="${ru?"Выйти из экскурсии":"Sayohatdan chiqish"}">${ru?"Выйти":"Chiqish"} ✕</button><div class="tour-t">${tourTx(s.t)}</div><div class="tour-f"><span class="tour-n">${TOUR.i+1}/${TOUR_S.length}</span>${sol}${nx}</div>`;
  spot.classList.toggle("tap",!!s.tap); spot.classList.toggle("ctr",!!s.center);
  const place=()=>{ if(el&&!el.isConnected){ const e2=tourFind(s.sel); if(e2) el=e2; } const vw=innerWidth, vh=(window.visualViewport&&visualViewport.height)||innerHeight; let r=el?el.getBoundingClientRect():{left:vw/2,top:vh/2,width:0,height:0,right:vw/2,bottom:vh/2};
    const pad=6, L=Math.max(4,r.left-pad), T=Math.max(4,r.top-pad), W=Math.min(vw-8,r.width+pad*2), H=Math.min(vh-8,r.height+pad*2);
    Object.assign(spot.style,{left:L+"px",top:T+"px",width:(el?W:0)+"px",height:(el?H:0)+"px",opacity:"1"});
    const bw=Math.min(340,vw-24); bub.style.width=bw+"px"; const bh=bub.offsetHeight||120; let bx=Math.min(Math.max(12,r.left+r.width/2-bw/2),vw-bw-12), by;
    if(!el) by=vh/2-bh/2; else if(s.free) by=vh-bh-12; /* mashq paytida pufakcha pastda — Prüfen/Weiter yopilmasin */ else if(r.bottom+bh+18<vh) by=Math.min(r.bottom+14,vh-bh-12); else if(r.top-bh-18>0) by=r.top-bh-14; else by=Math.max(12,vh-bh-12);
    Object.assign(bub.style,{left:bx+"px",top:by+"px",opacity:"1"}); TOUR.raf=requestAnimationFrame(place); };
  cancelAnimationFrame(TOUR.raf); place(); }
/* sayohat paytida faqat yoritilgan joy bosiladi */
["pointerdown","click"].forEach(tp=>document.addEventListener(tp,e=>{ if(!TOUR.on) return; const s=TOUR.cur; const tb=e.target.closest&&e.target.closest("[data-tour]");
  if(tb){ if(tp==="click"){ e.preventDefault(); const a=tb.dataset.tour; if(a==="skip"){ try{ if(!exEl().hidden) exClose(); }catch(er){} try{ if(!lrnEl().hidden) lrnClose(); }catch(er){} tourEnd(false); } else if(a==="next") tourNext(); else if(a==="tap") tourTap(); else if(a==="sol"){ try{ if(!EX.done) exSol(); }catch(er){} } } return; }
  if(e.target.closest&&e.target.closest("#tour-bub")){ if(tp==="click"&&s&&s.tap) tourTap(); return; }
  const el=s&&!s.center?tourFind(s.sel):null, fr=s&&s.free?document.querySelector(s.free):null;
  if((s&&s.tap&&el&&el.contains(e.target))||(fr&&fr.contains(e.target))){ if(tp==="click"&&s.tap&&!s._dyn&&!TOUR.adv){ TOUR.adv=true; setTimeout(tourNext,450); } return; }
  e.preventDefault(); e.stopPropagation(); e.stopImmediatePropagation(); },true));
