  const D=lernData(); TP.ltLv=TP.ltLv||(TABS[state.tab]&&/^(A[12]|B1)$/.test(TABS[state.tab].lvl)?TABS[state.tab].lvl:"A2"); TP.ltLang=TP.ltLang||(state.lang==="ru"?"ru":"uz");
