  const les=Object.keys(L.les).map(Number).filter(n=>TP.ltH===2?n>12:n<=12); [...TP.sel].forEach(n=>{ if(!les.includes(n)) TP.sel.delete(n); }); if(!TP.sel.size&&les.length) TP.sel.add(les[0]);
