  const S=all.map(([id,d])=>[id,d,anStu(d,P)]), act=S.filter(x=>x[2].min>0);
  const T=k=>S.reduce((s,x)=>s+(x[2][k]||0),0); const ans=T("ans"), first=T("first"), sol=T("sol"), sk=T("sk"), mins=T("min");
  const pc=(a,b)=>b?Math.round(a/b*100)+"%":"—";
  /* kunlik */
