function chEl(){ let e=document.getElementById("chal"); if(!e){ e=document.createElement("div"); e.id="chal"; e.className="lrn"; e.setAttribute("role","dialog"); e.setAttribute("aria-modal","true"); e.hidden=true; document.body.appendChild(e); } return e; }
/* Grammatik challenge (2026-10-22): c.xs=[[mashq id, bo'lim],…] — tanlangan Lektionlarning Grammatik bo'limlari birga */
function chXQs(c){ if(c.xs){ const seen=new Set(); return c.xs.flatMap(([id,si])=>exGameQs(id,si)).filter(q=>!seen.has(q.q)&&seen.add(q.q)); } return c.x?exGameQs(c.x,c.si):[]; }
function tpGrSecs(lv,ls){ if(CH_GR[lv]) return ls.filter(n=>(CH_GR[lv][n]||[]).length>=4).map(n=>["gr:"+lv,n]); const D=exData(), out=[]; for(const id in D){ const m=byId[id]; if(!m||m.lvl!==lv||!ls.includes(+m.key)) continue; (D[id].sec||[]).forEach((s,si)=>{ if(/Grammatik/i.test(s.t||"")&&exGameQs(id,si).length>=4) out.push([id,si]); }); } return out; }
function chPool(c){ if(c.x||c.xs) return chXQs(c); const D=lernData()[c.l]; if(!D) return []; return D.it.map((r,i)=>({i,l:r[0],de:r[3],ru:r[4],red:r[6],dis:r[7]})).filter(x=>x.ru && !x.red && c.s.includes(x.l)); }
function chTitle(c){ if(c.xs) return "📘 Grammatik "+(c.lv||"")+" · "+(c.ls||[]).map(n=>"L"+n).join(", "); if(c.x){ try{ const D=exData()[c.x], sc=D.sec[c.si]; return (D.title||"")+(D.sec.length>1?" · "+(sc.ic||"")+" "+(sc.t||""):""); }catch(e){ return ""; } } const m=byId[c.l]; const D=lernData()[c.l]; const lab=n=>(D&&D.lab&&D.lab[n])||("L"+n); return (m?m.title:(D&&D.title)||"")+" · "+c.s.map(lab).join(", "); }
function chPts(){ return !!(CHS.c&&CHS.c.v>=2); }
function chQuestions(c){
  if(c.x||c.xs){ const base=chXQs(c); if(base.length<4) return []; const r=chRng(c.r), qs=[]; while(qs.length<160){ for(const x of chShuf(base.slice(),r)){ const o=x.gp?[x.a,...chShuf(x.gp.slice(),r).slice(0,3)]:x.o.slice(); qs.push({q:x.q,a:x.a,o:chShuf(o,r)}); if(qs.length>=160) break; } } return qs; }
  const pool=chPool(c); if(pool.length<4) return []; const r=chRng(c.r); const qs=[];
  while(qs.length<160){ for(const x of chShuf(pool.slice(),r)){
    let opts;
    if(x.dis&&x.dis.length>=3) opts=[x.de,...x.dis.slice(0,3)];
    else { const art=/^(der|die|das) /.test(x.de); let cand=pool.filter(y=>y.de!==x.de && /^(der|die|das) /.test(y.de)===art); if(cand.length<3) cand=pool.filter(y=>y.de!==x.de);
      const seen=new Set([x.de]); opts=[x.de]; for(const y of chShuf(cand.slice(),r)){ if(!seen.has(y.de)){ seen.add(y.de); opts.push(y.de); } if(opts.length===4) break; } }
    qs.push({q:x.ru, a:x.de, o:chShuf(opts,r)}); if(qs.length>=160) break; } }
  return qs;
}
function chLink(code){ return (/github\.io$/.test(location.hostname)||!/claude/.test(location.hostname)&&location.protocol!=="file:" ? location.origin+location.pathname : CH_SITE)+"?ch="+code; }
function chLib(cb){ if(window.mqtt) return cb(); let s=document.getElementById("mqtt-js"); if(!s){ s=document.createElement("script"); s.id="mqtt-js"; s.src="files/js/mqtt.min.js"; s.async=true; document.head.appendChild(s); } s.addEventListener("load",()=>cb()); s.addEventListener("error",()=>chSetNet("bad")); }
/* --- yaratish (Yodlash oynasidan) --- */
function chCreate(){
  if(!LR.id||!LR.sel.size) return;
  const c={v:2,l:LR.id,s:[...LR.sel].sort((a,b)=>a-b),r:Math.floor(Math.random()*2147483647),c:window.BLITZ?"Blitz":((ACC.name||"").split(" ")[0]||""),t:Date.now()};
  const code=chB64e(JSON.stringify(c)), url=chLink(code), title=chTitle(c);
  try{ hpChMine(chHash(code)); actEv("game","chcreate"); }catch(e){}
  const txt=ct("tgText")(c.c||"⚡",title);
  lrnEl().querySelector(".lrn-body").innerHTML=`<div class="lrn-card"><h3>${esc(ct("made"))}</h3><p class="ch-big">${esc(ct("share"))}</p>
    <div class="ch-link">${esc(url)}</div><p class="ch-net">${esc(title)}</p>
    <div class="ch-btns"><a class="btn primary" target="_blank" rel="noopener" href="https://t.me/share/url?url=${encodeURIComponent(url)}&text=${encodeURIComponent(txt)}">${esc(ct("tg"))}</a>
    <button type="button" class="btn" data-ch="copy" data-url="${esc(url)}">${esc(ct("copy"))}</button>
    <button type="button" class="btn" data-ch="play" data-code="${esc(code)}">${esc(ct("playToo"))}</button></div>
    <button type="button" class="lrn-link" data-l="back">← ${esc(lt("back"))}</button></div>`;
}
/* --- jonli natijalar --- */
function chConnect(){
  if(CHS.cli) return; if(!window.mqtt){ chLib(()=>{ if(window.mqtt) chConnect(); }); return; }
  let bi=0;
  const go=()=>{ const cli=window.mqtt.connect(CH_BROKERS[bi],{clientId:"od_"+CHS.me+"_"+Math.random().toString(36).slice(2,7),clean:true,connectTimeout:8000,reconnectPeriod:3000,keepalive:30});
    CHS.cli=cli; let ok=false;
    cli.on("connect",()=>{ ok=true; chSetNet("ok"); cli.subscribe(CH_NS+CHS.id+"/p/+",{qos:1}); chPublish(true); });
    cli.on("message",(tp,buf)=>{ const pid=tp.split("/").pop(); try{ const d=JSON.parse(buf.toString()); if(d&&typeof d.s==="number") CHS.players[pid]={cx:Math.min(99,d.cx|0),hl:Math.min(4,d.hl|0),n:String(d.n||"?").slice(0,40),s:d.s|0,st:d.st,t:d.t||0,g:Array.isArray(d.g)?d.g.slice(0,300).map(Number).filter(x=>x>=0&&x<=CH_SEC+1):null}; }catch(e){} chRenderBoard(); });
    cli.on("offline",()=>chSetNet("wait"));
    cli.on("error",()=>{});
    setTimeout(()=>{ if(!ok && bi+1<CH_BROKERS.length){ try{ cli.end(true); }catch(e){} bi++; CHS.cli=null; go(); } else if(!ok) chSetNet("bad"); },9000);
  };
  go();
}
function chPublish(force){
  const cli=CHS.cli; if(!cli||!cli.connected||!CHS.name||!(CHS.phase==="play"||CHS.phase==="end")) return;
  const now=Date.now(); if(!force && now-CHS.pubT<700){ clearTimeout(CHS.pubTm); CHS.pubTm=setTimeout(()=>chPublish(true),700); return; }
  CHS.pubT=now;
  const d={n:CHS.name,hl:hpMyLv(),s:CHS.score,a:CHS.ans,cx:CHS.cx|0,st:CHS.phase==="end"?"done":"live",t:CHS.phase==="end"?CHS.tEnd:now};
  if(CHS.phase==="end"&&CHS.gt&&CHS.gt.length) d.g=CHS.gt;
  cli.publish(CH_NS+CHS.id+"/p/"+CHS.me,JSON.stringify(d),{qos:1,retain:true});
}
function chSetNet(s){ CHS.net=s; const e=document.getElementById("ch-net"); if(e) e.textContent=ct(s==="ok"?"netOk":s==="bad"?"netBad":"netWait"); }
function chRanked(){
  const P=Object.assign({},CHS.players);
  if(CHS.name&&(CHS.phase==="play"||CHS.phase==="end")) P[CHS.me]={n:CHS.name,s:CHS.score,st:CHS.phase==="end"?"done":"live",t:CHS.phase==="end"?CHS.tEnd:Date.now()};
  return Object.entries(P).map(([id,p])=>({id,...p})).sort((a,b)=>b.s-a.s||(a.t||0)-(b.t||0));
}
function chBoardHTML(mini){
  const L=chRanked(); if(!L.length) return `<p class="ch-net">${esc(ct("empty"))}</p>`;
  const lim=mini?5:50; let rows=L.slice(0,lim); const mi=L.findIndex(p=>p.id===CHS.me); if(mi>=lim) rows=[...rows.slice(0,lim-1),L[mi]];
  const medal=k=>k===0?"🥇":k===1?"🥈":k===2?"🥉":String(k+1);
  return `<ol class="ch-lb${mini?" ch-mini":""}">`+rows.map(p=>{ const k=L.indexOf(p);
    return `<li class="${p.id===CHS.me?"me":""}"><span class="pl">${medal(k)}</span><span class="nm">${esc(p.n)}${p.id===CHS.me?` (${esc(ct("you"))})`:""}${hpBadgeLv(p.id===CHS.me?hpMyLv():p.hl,true)}${p.cx?`<i class="kg-cx">👀×${p.cx}</i>`:""}${p.st==="live"&&p.id!==CHS.me?`<span class="lv">● ${esc(ct("live"))}</span>`:""}</span><span class="sc">${p.s}</span></li>`; }).join("")+`</ol>`;
}
function chRenderBoard(){ try{ hpChScan(); }catch(e){}
  const b=document.getElementById("ch-board"); if(b) b.innerHTML=chBoardHTML(CHS.phase==="play");
  const r=document.getElementById("ch-rank"); if(r){ const L=chRanked(); const k=L.findIndex(p=>p.id===CHS.me); r.textContent="🏅 "+ct("place")(k+1,L.length); }
}
/* --- o'yin --- */
function chHead(sub){ return `<div class="lrn-bar"><button class="btn" data-ch="close" aria-label="✕">✕</button><div class="lrn-tt"><b>${esc(ct("title"))}</b><small>${esc(chTitle(CHS.c))}</small></div>${sub||""}</div>`; }
function chOpen(code){
  let c=null; try{ c=JSON.parse(chB64d(code)); }catch(e){}
  const el=chEl(); el.hidden=false; document.body.style.overflow="hidden";
  if(!c||!(c.xs?c.xs.length:c.x?exData()[c.x]:lernData()[c.l])||chQuestions(c).length===0){ el.innerHTML=`<div class="lrn-bar"><button class="btn" data-ch="close">✕</button><div class="lrn-tt"><b>${esc(ct("title"))}</b></div></div><div class="lrn-body"><div class="lrn-card"><p>${esc(ct("bad"))}</p></div></div>`; return; }
  Object.assign(CHS,{cx:0,c,id:chHash(code),qs:chQuestions(c),players:{},phase:"lobby",score:0,ans:0,qi:0});
  let me=store.get("chme"); if(!me){ me=Math.random().toString(36).slice(2,10); store.set("chme",me); } CHS.me=me;
  const prev=store.get("chdone:"+CHS.id); if(prev){ try{ const p=JSON.parse(prev); Object.assign(CHS,{name:p.n,score:p.s,ans:p.a||0,tEnd:p.t,phase:"end"}); }catch(e){} }
  CHS.name=CHS.name||store.get("chname")||ACC.name||"";
  chConnect(); CHS.phase==="end"? chEnd(true) : chLobby();
}
function chLobby(){
  const c=CHS.c, n=chPool(c).length;
  chEl().innerHTML=chHead()+`<div class="lrn-body"><div class="lrn-card">
    ${c.c?`<h3>${esc(ct("from")(c.c))}</h3>`:""}<p class="ch-big"><b>${esc(chTitle(c))}</b> · ${esc(c.x||c.xs?(state.lang==="ru"?n+" вопросов":n+" ta savol"):ct("words")(n))}</p><p class="ch-big">⏱ ${esc(ct(c.v>=2?"rulesP":"rules"))}</p>
    <label class="acc-lb">${esc(ct("name"))}<input class="ch-in" id="ch-name" maxlength="30" placeholder="${esc(ct("namePh"))}" value="${esc(CHS.name)}"></label>
    <div class="acc-st err" id="ch-err"></div>
    <button type="button" class="btn primary" data-ch="start">${esc(ct("start"))} →</button>
    <p class="ch-net" id="ch-net"></p></div>
    <div class="lrn-card"><h3>${esc(ct("board"))}</h3><div id="ch-board"></div></div></div>`;
  chSetNet(CHS.net); chRenderBoard();
}
function chStart(){
  const inp=document.getElementById("ch-name"), nm=(inp.value||"").replace(/\s+/g," ").trim();
  if(nm.length<2){ document.getElementById("ch-err").textContent=ct("errName"); inp.focus(); return; }
  CHS.name=nm; store.set("chname",nm); CHS.phase="count"; let k=3;
  const tick=()=>{ if(k===0){ chPlay(); return; } chEl().innerHTML=chHead()+`<div class="lrn-body"><div class="ch-cd">${k}</div></div>`; k--; setTimeout(tick,800); };
  tick();
}
/* 🏆 Rekordchi bilan poyga: rekordchining o'yini soniyama-soniya qayta ko'rsatiladi (faqat ko'rsatadi, ballga ta'sir qilmaydi) — 2026-10-18 */
function chGhostPick(){ const G=Object.entries(CHS.players).filter(([id,p])=>id!==CHS.me&&p.st==="done"&&p.g&&p.g.length>0&&(chPts()||p.g.length===p.s)).sort((a,b)=>b[1].s-a[1].s||(a[1].t||0)-(b[1].t||0))[0];
  return G?{n:G[1].n,s:G[1].g.length,g:G[1].g.slice().sort((a,b)=>a-b)}:null; }
function chGhostDraw(){ const el=document.getElementById("ch-ghost"); if(!el) return; const uz=state.lang!=="ru", G=CHS.ghost;
  if(!G){ el.innerHTML=`<div class="gh-solo">🏆 ${uz?"Hali rekord yo‘q — siz birinchisiz! Rekord o‘rnating.":"Рекорда пока нет — установите его первым!"}</div>`; return; }
  const e=(performance.now()-CHS.t0)/1000, gs=G.g.filter(x=>x<=e).length, me=chPts()?(CHS.okN||0):CHS.score, mx=Math.max(G.s,me,1), d=me-gs;
  const first=G.n.split(" ")[0];
  el.innerHTML=`<div class="gh-lane gh-g"><span class="gh-l">🏆 ${esc(first)}</span><span class="gh-t"><i style="width:${gs/mx*100}%"></i></span><b>${gs}</b></div>
    <div class="gh-lane gh-me"><span class="gh-l">🏃 ${uz?"Siz":"Вы"}</span><span class="gh-t"><i style="width:${me/mx*100}%"></i></span><b>${me}</b></div>
    <div class="gh-msg ${d>0?"up":d<0?"down":""}">${d>0?(uz?`💪 Rekordchidan ${d} ta oldindasiz!`:`💪 Вы впереди рекордсмена на ${d}!`):d<0?(uz?`🏆 Rekordchi ${-d} ta oldinda — tezlashing!`:`🏆 Рекордсмен впереди на ${-d} — быстрее!`):(uz?"⚖️ Teng ketyapsiz!":"⚖️ Идёте вровень!")}${G.s?` <small>${uz?`rekord: ${G.s}`:`рекорд: ${G.s}`}</small>`:""}</div>`; }
function chPlay(){
  Object.assign(CHS,{phase:"play",score:0,okN:0,ans:0,qi:0,t0:performance.now(),gt:[],ghost:chGhostPick()});
  chEl().innerHTML=chHead(`<span class="ch-time" id="ch-time">${CH_SEC}</span>`)+`<div class="lrn-body">
    <div class="ch-bar"><i id="ch-tb" style="width:100%"></i></div>
    <div class="ch-ghost" id="ch-ghost"></div>
    <div class="ch-top"><span class="ch-score" id="ch-score">${esc(ct("score")(0))}</span><span class="ch-rank" id="ch-rank"></span></div>
    <div class="lrn-card" id="ch-card"></div><div id="ch-board"></div><p class="ch-net" id="ch-net"></p></div>`;
  chSetNet(CHS.net); chQ(); chPublish(true); chRenderBoard();
  chGhostDraw();
  CHS.tm=setInterval(()=>{ const left=Math.max(0,CH_SEC-(performance.now()-CHS.t0)/1000); chGhostDraw();
    const t=document.getElementById("ch-time"); if(t) t.textContent=Math.ceil(left); const b=document.getElementById("ch-tb"); if(b) b.style.width=(left/CH_SEC*100)+"%";
    if(left<=0){ clearInterval(CHS.tm); chFinish(); } }, 200);
}
function chQ(){
  const q=CHS.qs[CHS.qi%CHS.qs.length]; CHS.cur=q; CHS.lock=false; CHS.qT=performance.now();
  const card=document.getElementById("ch-card"); if(!card) return;
  card.innerHTML=`<div class="ch-q">${esc(q.q)}</div><div class="lrn-ask">${esc(CHS.c.x||CHS.c.xs?(state.lang==="ru"?"Выберите правильный ответ":"To‘g‘ri javobni tanlang"):ct("choose"))}</div><div class="lrn-opts">${q.o.map((o,k)=>`<button type="button" class="lrn-opt" data-cho="${k}"><span class="k">${k+1}</span>${esc(o)}</button>`).join("")}</div>`;
}
function chAnswer(k){
  if(CHS.phase!=="play"||CHS.lock) return; CHS.lock=true;
  const q=CHS.cur, ok=q.o[k]===q.a, card=document.getElementById("ch-card");
  CHS.ans++; let pts=0;
  /* ⚡ Tezlik ballari (v2 challenge'lar): darrov javob = 1000, 10 soniya va undan ko'p = 500. Eski (v1) havolalar — 1 ball. */
  if(ok){ const dt=(performance.now()-(CHS.qT||performance.now()))/1000; pts=chPts()?Math.round(1000-500*Math.min(dt,10)/10):1; CHS.score+=pts; CHS.okN=(CHS.okN||0)+1; CHS.gt.push(Math.round((performance.now()-CHS.t0)/100)/10);
    if(chPts()){ const pp=document.createElement("div"); pp.className="ch-pts"; pp.textContent="+"+pts+(dt<2?" ⚡":""); card.appendChild(pp); } }
  card.querySelectorAll(".lrn-opt").forEach((b,j)=>{ b.disabled=true; if(q.o[j]===q.a) b.classList.add("ok"); else if(j===k) b.classList.add("bad"); });
  card.classList.remove("ch-flash-ok","ch-flash-bad"); void card.offsetWidth; card.classList.add(ok?"ch-flash-ok":"ch-flash-bad");
  document.getElementById("ch-score").textContent=ct("score")(CHS.score);
  chPublish(false); chRenderBoard();
  setTimeout(()=>{ if(CHS.phase!=="play") return; CHS.qi++; chQ(); }, ok?250:750);
}
function chFinish(){
  try{ actEv("game","ch"); }catch(e){}
  CHS.phase="end"; CHS.tEnd=Date.now(); gpAdd("ch",CHS.id,(CHS.okN||0)*10);
  store.set("chdone:"+CHS.id,JSON.stringify({n:CHS.name,s:CHS.score,a:CHS.ans,t:CHS.tEnd}));
  chPublish(true); chEnd(false);
}
function chEnd(again){
  const L=chRanked(), k=L.findIndex(p=>p.id===CHS.me);
  const url=chLink(new URLSearchParams(location.search).get("ch")||"");
  const ru=state.lang==="ru", txt=(ru?`⚡ ${chTitle(CHS.c)}\nУ меня ${CHS.score} баллов (${k+1}-е место). Попробуй обойти меня 😏`:`⚡ ${chTitle(CHS.c)}\nMen ${CHS.score} ball oldim (${k+1}-o‘rin). Meni yengib ko‘r 😏`);
  chEl().innerHTML=chHead()+`<div class="lrn-body"><div class="lrn-card lrn-end"><div class="big">🏆</div>
    <h3>${esc(again?ct("played"):ct("done"))}</h3><p class="ch-big" id="ch-res">${esc(ct("yourRes")(CHS.score,k+1,L.length))}</p>
    <div class="ch-btns" style="justify-content:center"><a class="btn primary" target="_blank" rel="noopener" href="https://t.me/share/url?url=${encodeURIComponent(url)}&text=${encodeURIComponent(txt)}">${esc(ct("invite"))}</a>
    <button type="button" class="btn" data-ch="copy" data-url="${esc(txt+"\n"+url)}">📋 ${ru?"Копировать":"Nusxalash"}</button><button type="button" class="btn" data-ch="close">${esc(ct("close"))}</button></div><p class="ch-net" id="ch-net"></p></div>
    <div class="lrn-card"><h3>${esc(ct("board"))}</h3><div id="ch-board"></div></div></div>`;
  chSetNet(CHS.net); chRenderBoard();
  const upd=()=>{ const r=document.getElementById("ch-res"); if(!r){ return; } const L2=chRanked(), k2=L2.findIndex(p=>p.id===CHS.me); r.textContent=ct("yourRes")(CHS.score,k2+1,L2.length); };
  clearInterval(CHS.endT); CHS.endT=setInterval(upd,1500);
}
function chClose(){
  clearInterval(CHS.tm); clearInterval(CHS.endT); if(CHS.phase==="play") chFinish();
  chEl().hidden=true; document.body.style.overflow=""; try{ if(CHS.cli) CHS.cli.end(); }catch(e){} CHS.cli=null; CHS.phase="";
  if(new URLSearchParams(location.search).get("ch")){ history.replaceState(null,"",location.pathname); if(!ACC.cur && ACC_OK) accLogin(); }
}
document.addEventListener("click",e=>{
  const m=e.target.closest('#lrn [data-l="chal"]'); if(m){ chCreate(); return; }
  const b=e.target.closest("[data-ch]"); if(b){ const a=b.dataset.ch;
    if(a==="copy"){ const u=b.dataset.url; (navigator.clipboard?navigator.clipboard.writeText(u):Promise.reject()).then(()=>{ b.textContent=ct("copied"); }).catch(()=>{ prompt("",u); }); }
    else if(a==="play"){ lrnClose(); history.replaceState(null,"","?ch="+b.dataset.code); chOpen(b.dataset.code); }
    else if(a==="start") chStart();
    else if(a==="close") chClose();
    return; }
  const o=e.target.closest("[data-cho]"); if(o) chAnswer(+o.dataset.cho);
});
document.addEventListener("keydown",e=>{ const el=document.getElementById("chal"); if(!el||el.hidden) return;
  if(CHS.phase==="play" && /^[1-4]$/.test(e.key)){ chAnswer(+e.key-1); }
  else if(CHS.phase==="lobby" && e.key==="Enter" && e.target.id==="ch-name"){ e.preventDefault(); chStart(); } });
(function(){ const code=new URLSearchParams(location.search).get("ch"); if(code) setTimeout(()=>chOpen(code),50); })();
